def solve_15_293(input_data: str) -> str:
    # TODO: DP, Two Pointers, Greedy 기반으로 풀어야 하지만 아직 설계가 덜 됨 (863)
    lines = input_data.strip().split()
    if not lines:
        return ""
    # 임시 처리: 첫 숫자만 반환 (오답 가능)
    try:
        return str(int(lines[0]))
    except:
        return lines[0]

